using System;using System.Linq;using System.IO;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;
internal class Check{
 static int Main(string[] args){for(int i=0;i<args.Length;i+=2){
 var left=CSharpSyntaxTree.ParseText(File.ReadAllText(args[i]));var right=CSharpSyntaxTree.ParseText(File.ReadAllText(args[i+1]));
 if(left.GetDiagnostics().Concat(right.GetDiagnostics()).Any(d=>d.Severity==DiagnosticSeverity.Error))return 1;
 var a=left.GetRoot();var b=right.GetRoot();
 if(!SyntaxFactory.AreEquivalent(a,b,topLevel:false))return 2;
 var x=a.DescendantTokens(descendIntoTrivia:true).Select(t=>(t.RawKind,t.Text,t.ValueText));var y=b.DescendantTokens(descendIntoTrivia:true).Select(t=>(t.RawKind,t.Text,t.ValueText));
 if(!x.SequenceEqual(y))return 3;Console.WriteLine(Path.GetFileName(args[i])+":"+x.Count());}return 0;}}
